(function(){var cf=document.querySelectorAll('.cf'),cl=['a','b','c','d'];[].forEach.call(document.querySelectorAll('.cn'),function(box){cl.forEach(function(c,k){if(!cf[k])return;var im=new Image();im.src=cf[k].src;im.alt='';im.className=c;box.appendChild(im)})})})();
// ---- calendar// ---- calendar (.ics, UTC times from Karachi local; stable UIDs so re-adding updates instead of duplicating)
function utc(d,t){var p=pd(d),h=t.split(':');return new Date(Date.UTC(p.y,p.m,p.d,+h[0]-C.tzHours,+h[1]))}
function z(d){return d.toISOString().replace(/[-:]|\.\d+/g,'')}
function esc(s){return String(s).replace(/\\/g,'\\\\').replace(/;/g,'\\;').replace(/,/g,'\\,').replace(/\r?\n/g,'\\n')}
var NOTE='Sample time and venue until confirmed by the family.';
function ics(a){var L=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Hamza Ayesha Invitation//EN','CALSCALE:GREGORIAN'];
 a.forEach(function(e){L.push('BEGIN:VEVENT','UID:'+e.id+'-'+e.date+'@hamza-ayesha-invitation','DTSTAMP:'+z(new Date()),'DTSTART:'+z(utc(e.date,e.start)),'DTEND:'+z(utc(e.date,e.end)),'SUMMARY:'+esc(e.t.en+' – Hamza & Ayesha'),'LOCATION:'+esc(e.venue+', '+e.addr),'DESCRIPTION:'+esc(e.sub+'. '+NOTE),'END:VEVENT')});
 L.push('END:VCALENDAR');return L.join('\r\n')+'\r\n'}
function dl(a,n){var l=document.createElement('a');l.href=URL.createObjectURL(new Blob([ics(a)],{type:'text/calendar;charset=utf-8'}));l.download='hamza-ayesha-'+n+'.ics';document.body.appendChild(l);l.click();l.remove()}
