// ---- countdown
var T=utc(EV[C.countdownEvent].date,EV[C.countdownEvent].start).getTime(),cdTimer;
function tick(){var s=Math.floor((T-Date.now())/1000);
 if(s<=0){$('cd').innerHTML='<h3 class="g" style="font-family:Cinzel,serif;font-size:4.2cqw;grid-column:1/-1;align-self:center">The celebrations have begun</h3>';$('cdl').textContent='';clearInterval(cdTimer);return}
 var v=[Math.floor(s/86400),Math.floor(s%86400/3600),Math.floor(s%3600/60),s%60],l=['Days','Hours','Minutes','Seconds'];
 $('cd').innerHTML=v.map(function(n,i){return '<div><b>'+(i?('0'+n).slice(-2):n)+'</b><span>'+l[i]+'</span></div>'}).join('');
 $('cdl').innerHTML='until the Reception · '+fd(EV[C.countdownEvent].date)+'<br>'+EV[C.countdownEvent].time.split(' – ')[0]+' · Pakistan time'}
tick();cdTimer=setInterval(tick,1000);
// ---- RSVP (demo mode by default; submitRSVP is the single place to connect a backend)
function submitRSVP(d){ // return a Promise; reject on failure. No secrets in frontend code – use a public endpoint that holds its own credentials.
 if(C.rsvp.demo||!C.rsvp.endpoint){console.info('RSVP (demo, not sent):',d);return Promise.resolve({demo:true})}
 return fetch(C.rsvp.endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}).then(function(r){if(!r.ok)throw new Error('HTTP '+r.status);return{demo:false}})}
var at=function(){return document.querySelector('input[name=at]:checked')};
[].forEach.call(document.querySelectorAll('input[name=at]'),function(r){r.onchange=function(){$('yw').style.display=at().value.indexOf('Reg')==0?'none':''}});
$('f').onsubmit=function(ev){ev.preventDefault();var m=$('rm'),sb=$('sb');m.textContent='';m.className='';
 var n=$('gn').value.trim(),g=+$('gc').value,yes=at()&&at().value.indexOf('Reg')!=0,evs=[].map.call(document.querySelectorAll('input[name=ev]:checked'),function(c){return c.value});
 $('e1').textContent=n?'':'Please enter your name.';$('e2').textContent=at()?'':'Please choose whether you can attend.';
 $('e4').textContent=(!yes||evs.length)?'':'Please select at least one event.';$('e3').textContent=(!yes||(g>=1&&g<=10))?'':'Enter a number of guests from 1 to 10.';
 if(!n||!at()||$('e4').textContent||$('e3').textContent){m.textContent='Please fix the highlighted fields.';return}
 var d={name:n,attendance:at().value,events:yes?evs:[],guests:yes?g:0,phone:$('ph').value.trim(),notes:$('nt').value.trim(),message:$('ms').value.trim(),submittedAt:new Date().toISOString()};
 sb.disabled=true;submitRSVP(d).then(function(r){m.className='ok';m.textContent=r.demo?'Demo mode: your answers are valid, but nothing was sent or saved yet.':'Thank you. Your RSVP has been sent.'}).catch(function(){m.textContent='Your RSVP could not be sent. Please check your connection and try again.'}).then(function(){sb.disabled=false})};
var rsx=$('rs');$('rb').onclick=function(){var o=!$('fw').classList.contains('open');$('fw').classList.toggle('open',o);rsx.classList.toggle('ro',o);this.setAttribute('aria-expanded',o);if(o)setTimeout(function(){$('fw').scrollIntoView({behavior:'smooth',block:'start'})},450)};
