for(var i=0;i<14;i++){var d=document.createElement('i');d.className='gp';d.style.cssText='left:'+Math.random()*100+'%;top:'+(15+Math.random()*70)+'%;animation-delay:-'+Math.random()*6+'s;animation-duration:'+(5+Math.random()*4)+'s';$('hero').appendChild(d)}
