// ---- music: 38 s of the flute. Each pass fades in mildly, fades out, stays silent for a moment, then starts again (no native looping).
var au=null,mus=$('mus'),want=true,envT=0,gapT=0,FIN=1.6,FOUT=2.6,VOL=.6;
function env(){if(!au||au.paused)return;var D=au.duration||38,t=au.currentTime,v=VOL*Math.min(1,t/FIN)*Math.min(1,Math.max(0,(D-.15-t)/FOUT));au.volume=Math.max(0,Math.min(1,v))}
function music(on){clearTimeout(gapT);if(!au)return Promise.resolve();if(on){au.volume=0;return au.play().then(function(){clearInterval(envT);envT=setInterval(env,80);mus.textContent='❚❚';mus.setAttribute('aria-label','Pause music')}).catch(function(){})}au.pause();clearInterval(envT);mus.textContent='♪';mus.setAttribute('aria-label','Play music');return Promise.resolve()}
if(C.music){au=new Audio('data:audio/mp4;base64,');au.loop=false;au.preload='auto';mus.onclick=function(){want=au.paused;music(want)};
  au.addEventListener('ended',function(){clearInterval(envT);au.volume=0;au.currentTime=0;gapT=setTimeout(function(){if(want&&!document.hidden)music(true)},1200)});
  document.addEventListener('visibilitychange',function(){if(document.hidden){au.pause();clearInterval(envT);clearTimeout(gapT)}else if(want&&fin)music(true)})}
// ---- opening → hero
var cv=$('cv'),ov=$('ov'),hv=$('hv'),started=0,fin=0,wd=0;
function playHero(){var p=hv.play();if(p&&p.catch)p.catch(function(){$('pp').style.display='block'})}
$('pp').onclick=function(){this.style.display='none';hv.play()};
function finish(){if(fin)return;fin=1;clearInterval(wd);cv.classList.add('out');document.body.classList.remove('lock');scrollTo(0,0);
 hv.currentTime=0;if(!rm)playHero();if(au){mus.style.display='block';if(want)setTimeout(function(){music(true)},rm?0:250)}setTimeout(function(){$('hero').classList.add('on')},rm?0:500);setTimeout(function(){cv.style.display='none';ov.pause()},rm?50:2100)}
function openEnv(){if(started)return;started=1;cv.classList.add('go');if(au){au.volume=0;au.play().then(function(){au.pause();au.currentTime=0}).catch(function(){})}
 if(rm){finish();return}
 var pr=ov.play();if(pr&&pr.catch)pr.catch(finish);
 wd=setInterval(function(){if(ov.ended||ov.currentTime>=4)finish()},60);setTimeout(finish,7000)}
ov.onerror=function(){if(started)finish()};
cv.onclick=openEnv;cv.onkeydown=function(e){if(e.key=='Enter'||e.key==' '){e.preventDefault();openEnv()}};
$('rp').onclick=function(){started=0;fin=0;cv.style.display='';cv.className='';ov.currentTime=0;ov.pause();hv.pause();hv.currentTime=0;$('hero').classList.remove('on');$('lb').classList.remove('in');watchLb();want=true;if(au){au.pause();clearInterval(envT);clearTimeout(gapT);au.currentTime=0;mus.textContent='♪'}document.body.classList.add('lock');scrollTo(0,0)};